def priority(task, state, m=5.0, k=0.5, q_hi=0.7, q_lo=0.3):
    import math
    est = max(task.estimated_runtime, 1e-6)
    slack = task.due - est - state.now
    tier = m if task.tenant == 'premium' else 1.0
    atc = task.weight / est * math.exp(-max(0.0, slack) / (k * max(state.mean_est, 1e-6)))
    minslack = -(slack)
    load = state.queue_work / max(state.capacity * max(state.mean_est, 1e-6), 1e-6)
    if load > q_hi:
        return tier * (0.2 * minslack + 1.5 * atc)
    elif load < q_lo:
        return tier * (1.5 * minslack + 0.2 * atc)
    return tier * (minslack + atc)

def priority(task, state):
    # Weighted EDF: earlier due and higher weight first
    w = max(task.weight, 1e-6)
    return w / max(task.due - state.now, 1e-6)

def priority(task, state):
    # Value-at-risk: weight times fraction of value still salvageable, scaled by urgency
    est = max(task.estimated_runtime, 1e-6)
    remaining = task.due - state.now
    decay_window = 2.0 * est
    if remaining >= 0:
        salvage = 1.0
    elif remaining <= -decay_window:
        salvage = 0.0
    else:
        salvage = 1.0 + remaining / decay_window
    urgency = 1.0 / max(remaining + est, 1e-6)
    return task.weight * salvage * urgency

def priority(task, state):
    # Tenant-aware EDF: premium tenants get boosted, plus type-specific urgency
    tenant_boost = 2.0 if task.tenant == 'premium' else 1.0
    type_boost = 1.2 if task.task_type == 'variant_calling' else 1.0
    return tenant_boost * type_boost * task.weight / max(task.due - state.now, 1e-6)

