def priority(task, state, k=1.0, m=4.0, eps=1e-6):
    import math
    slack = task.due - state.now - task.estimated_runtime
    lateness = max(0.0, -slack)
    tier = m if task.tenant == 'premium' else 1.0
    urgency = math.exp(-max(0.0, slack) / (k * max(state.mean_est, eps)))
    decay_horizon = max(2.0 * task.estimated_runtime, eps)
    value_risk = 1.0 + lateness / decay_horizon
    wait = max(0.0, state.now - task.release)
    age = 1.0 + wait / max(task.estimated_runtime, eps)
    return tier * task.weight * urgency * value_risk * age / max(task.estimated_runtime, eps)
```

