def priority(task, state, k=0.75, m=3.0, q=0.5, eps=1e-6):
    import math
    slack = task.due - state.now - task.estimated_runtime
    if slack >= 0.0:
        tier = m if task.tenant == 'premium' else 1.0
        return tier * task.weight / max(task.estimated_runtime, eps) * math.exp(
            -slack / (k * max(state.mean_est, eps))
        )
    late = -slack
    decay = max(2.0 * task.estimated_runtime, eps)
    remaining_value = max(0.0, 1.0 - late / decay)
    tier = (m if task.tenant == 'premium' else 1.0) ** (1.0 + q * late / decay)
    return tier * task.weight * remaining_value / max(task.estimated_runtime, eps)
