def priority(task, state, k=0.5, m=2.0, c=1.0, eps=1e-6):
    # ATC with a "slack-to-due" ratio that switches behavior based on whether
    # the job is comfortably schedulable or critically tight.
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    atc = tier * task.weight / max(task.estimated_runtime, eps) * math.exp(-slack / (k * max(state.mean_est, eps)))
    tightness = slack / max(task.estimated_runtime, eps)
    # If tight, boost strongly; if loose, mild boost to avoid starving.
    if tightness < 1.0:
        return atc * (1.0 + c * (1.0 - tightness))
    return atc * (1.0 + c / (1.0 + tightness))

