def priority(task, state, k=1.0, m=3.0, c=1.5, eps=1e-6):
    # Two-phase guard: if task is within c*est of due or already late,
    # rank by absolute due date scaled by value density; otherwise ATC.
    est = max(task.estimated_runtime, eps)
    now = state.now
    mean_est = max(state.mean_est, eps)
    tier = m if task.tenant == 'premium' else 1.0
    time_to_due = task.due - now
    if time_to_due <= c * est:
        # Near or past due: absolute due-date priority weighted by value/core.
        return tier * task.weight / est * (1.0 + max(0.0, c * est - time_to_due) / est)
    slack = max(0.0, task.due - est - now)
    return tier * task.weight / est * math.exp(-slack / (k * mean_est))

