def priority(task, state, k=0.6, m=3.0, q_thresh=8.0, eps=1e-6):
    import math
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    atc = task.weight / max(task.estimated_runtime, eps) * math.exp(-slack / (k * max(state.mean_est, eps)))
    if state.queue_len > q_thresh:
        # under congestion, favor short jobs to drain queue and reduce lateness
        return tier * atc / max(task.estimated_runtime, eps)
    else:
        # under light load, protect due dates more strictly (EDF-like)
        return -max(task.due, state.now + task.estimated_runtime) + tier * atc

